// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/me/applications", wrapper.ListMyApplications)
	m.HandleFunc("POST "+options.BaseURL+"/me/applications", wrapper.CreateApplication)
	m.HandleFunc("GET "+options.BaseURL+"/me/applications/{application_id}", wrapper.GetMyApplication)
	m.HandleFunc("POST "+options.BaseURL+"/me/applications/{application_id}/attachments", wrapper.UploadMyAttachment)
	m.HandleFunc("GET "+options.BaseURL+"/me/applications/{application_id}/attachments/{attachment_id}", wrapper.DownloadMyAttachment)
	m.HandleFunc("POST "+options.BaseURL+"/me/applications/{application_id}/cancel", wrapper.CancelMyApplication)
	m.HandleFunc("GET "+options.BaseURL+"/me/applications/{application_id}/certificate.pdf", wrapper.DownloadMyCertificate)
	m.HandleFunc("POST "+options.BaseURL+"/me/applications/{application_id}/messages", wrapper.PostMyMessage)
	m.HandleFunc("GET "+options.BaseURL+"/public/certificates/{code}", wrapper.VerifyCertificate)
	m.HandleFunc("GET "+options.BaseURL+"/service-types", wrapper.ListServiceTypes)
	m.HandleFunc("GET "+options.BaseURL+"/staff/applications", wrapper.ListStaffApplications)
	m.HandleFunc("GET "+options.BaseURL+"/staff/applications/{application_id}", wrapper.GetStaffApplication)
	m.HandleFunc("POST "+options.BaseURL+"/staff/applications/{application_id}/attachments", wrapper.UploadStaffAttachment)
	m.HandleFunc("GET "+options.BaseURL+"/staff/applications/{application_id}/attachments/{attachment_id}", wrapper.DownloadStaffAttachment)
	m.HandleFunc("POST "+options.BaseURL+"/staff/applications/{application_id}/messages", wrapper.PostStaffMessage)
	m.HandleFunc("POST "+options.BaseURL+"/staff/applications/{application_id}/status", wrapper.ChangeApplicationStatus)
	m.HandleFunc("GET "+options.BaseURL+"/staff/stats", wrapper.GetStaffStats)

	return m
}

