// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Мои заявки (F4)
	// (GET /me/applications)
	ListMyApplications(ctx context.Context, request ListMyApplicationsRequestObject) (ListMyApplicationsResponseObject, error)
	// Подать заявку
	// (POST /me/applications)
	CreateApplication(ctx context.Context, request CreateApplicationRequestObject) (CreateApplicationResponseObject, error)
	// Заявка с историей, перепиской и вложениями
	// (GET /me/applications/{application_id})
	GetMyApplication(ctx context.Context, request GetMyApplicationRequestObject) (GetMyApplicationResponseObject, error)
	// Приложить файл к заявке
	// (POST /me/applications/{application_id}/attachments)
	UploadMyAttachment(ctx context.Context, request UploadMyAttachmentRequestObject) (UploadMyAttachmentResponseObject, error)
	// Скачать вложение
	// (GET /me/applications/{application_id}/attachments/{attachment_id})
	DownloadMyAttachment(ctx context.Context, request DownloadMyAttachmentRequestObject) (DownloadMyAttachmentResponseObject, error)
	// Отозвать заявку
	// (POST /me/applications/{application_id}/cancel)
	CancelMyApplication(ctx context.Context, request CancelMyApplicationRequestObject) (CancelMyApplicationResponseObject, error)
	// Скачать справку с места учёбы (I1)
	// (GET /me/applications/{application_id}/certificate.pdf)
	DownloadMyCertificate(ctx context.Context, request DownloadMyCertificateRequestObject) (DownloadMyCertificateResponseObject, error)
	// Написать в деканат по заявке (I3)
	// (POST /me/applications/{application_id}/messages)
	PostMyMessage(ctx context.Context, request PostMyMessageRequestObject) (PostMyMessageResponseObject, error)
	// Проверка справки по коду
	// (GET /public/certificates/{code})
	VerifyCertificate(ctx context.Context, request VerifyCertificateRequestObject) (VerifyCertificateResponseObject, error)
	// Каталог услуг
	// (GET /service-types)
	ListServiceTypes(ctx context.Context, request ListServiceTypesRequestObject) (ListServiceTypesResponseObject, error)
	// Входящие заявки
	// (GET /staff/applications)
	ListStaffApplications(ctx context.Context, request ListStaffApplicationsRequestObject) (ListStaffApplicationsResponseObject, error)
	// Заявка для сотрудника
	// (GET /staff/applications/{application_id})
	GetStaffApplication(ctx context.Context, request GetStaffApplicationRequestObject) (GetStaffApplicationResponseObject, error)
	// Приложить документ (например, готовую справку)
	// (POST /staff/applications/{application_id}/attachments)
	UploadStaffAttachment(ctx context.Context, request UploadStaffAttachmentRequestObject) (UploadStaffAttachmentResponseObject, error)
	// Скачать вложение
	// (GET /staff/applications/{application_id}/attachments/{attachment_id})
	DownloadStaffAttachment(ctx context.Context, request DownloadStaffAttachmentRequestObject) (DownloadStaffAttachmentResponseObject, error)
	// Ответить студенту по заявке (I3)
	// (POST /staff/applications/{application_id}/messages)
	PostStaffMessage(ctx context.Context, request PostStaffMessageRequestObject) (PostStaffMessageResponseObject, error)
	// Сменить статус заявки
	// (POST /staff/applications/{application_id}/status)
	ChangeApplicationStatus(ctx context.Context, request ChangeApplicationStatusRequestObject) (ChangeApplicationStatusResponseObject, error)
	// Счётчики для главной сотрудника
	// (GET /staff/stats)
	GetStaffStats(ctx context.Context, request GetStaffStatsRequestObject) (GetStaffStatsResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

